const activeRules=()=>liveData?.alertState?.rules||[];
const ruleStatus={paused:'已暂停',watching:'监测中',missing_data:'等待有效数据'};
renderRules=function(){
 const data=liveData?.alertState||{},rules=activeRules().filter(r=>!state.query||(r.name+' '+catalog.find(p=>p.id===r.p)?.name).toLowerCase().includes(state.query.toLowerCase()));
 $('#page-subtitle').textContent='服务运行时后台检查，触发结果保存在本地服务。';
 $('#feed').innerHTML=`<div class="feed-toolbar"><span>${rules.length} 条后台规则</span><button class="primary" data-action="rule">＋ 新建规则</button></div><p class="module-note">每 20 秒检查最新采集数据；行情通常每分钟更新。首次数据建立基线，突破使用规则所选周期的已收盘 K 线。记录保存在站内，可选择本浏览器提醒。</p>${rules.map(r=>{const rt=data.runtime?.[r.id]||{};return `<article class="rule-card"><div class="rule-head"><div><h3>${escapeHtml(r.name)}</h3><span class="tag">${escapeHtml(catalog.find(p=>p.id===r.p)?.name||r.p)}</span> <span class="rule-status">${r.on?(ruleStatus[rt.status]||'等待首次检查'):'已暂停'}</span></div><button class="switch" role="switch" aria-label="启用 ${escapeHtml(r.name)}" aria-checked="${r.on}" data-toggle-rule="${r.id}"></button></div><p>${escapeHtml(ruleDescription(r))}<br>冷却 ${r.cooldownMinutes} 分钟 · 仅站内记录</p><small>最近检查：${formatTime(rt.checkedAt)}</small><div class="rule-actions"><button data-edit-rule="${r.id}">编辑规则</button><button data-delete-rule="${r.id}">删除</button></div></article>`}).join('')||'<div class="empty">尚无后台规则。点击“新建规则”开始监测。</div>'}<section class="alert-history"><h3>触发记录</h3><p class="module-note">保留最近 500 条。没有记录表示尚未触发，不代表没有市场风险。</p>${(data.alerts||[]).slice().reverse().map(a=>`<details class="related-report"><summary>${escapeHtml(a.ruleName)} · ${formatTime(a.at)}</summary><p>${escapeHtml(a.type==='news'?(a.titleZh||'重点消息候选，中文译文生成中；可查看来源原文'):a.title)}</p><div class="evidence">${Object.entries(a.evidence||{}).filter(([k])=>!['url','eventId'].includes(k)).map(([k,v])=>`${escapeHtml(({source:'数据来源',symbol:'交易对',period:'计算周期',oiAt:'OI 数据时间',previousClose:'前一根收盘',close:'本次收盘',candleAt:'K 线时间',sampleAt:'数据时间',threshold:'阈值',change24h:'24h 价格变化 %',oiChange1h:'1h OI 变化 %',ema200:'EMA 200',ema360:'EMA 360',level:'关键价位',reason:'触发依据',note:'说明',publishedAt:'发布时间'})[k]||k)}：${escapeHtml(k.endsWith('At')?formatTime(v):v)}`).join('<br>')}</div>${a.evidence?.url?`<a class="evidence-link" target="_blank" rel="noopener noreferrer" href="${escapeHtml(safeUrl(a.evidence.url))}">来源原文 ↗</a>`:''}</details>`).join('')||'<p class="module-empty">暂无触发记录</p>'}</section>`;
};
ruleDescription=function(r){const period=({'1h':'1 小时','4h':'4 小时','1d':'日线'})[r.period]||'4 小时';return r.type==='news'?'新重点消息及金额、比例、状态变化的后续进展候选；重复表述不重报':r.type==='ema'?`${period}收盘从非双线上方进入 EMA 200 / 360 双线上方`:r.type==='level'?`${period}收盘上穿 $${r.threshold}`:r.type==='combo'?`${period}收盘上穿双均线，且最新 1h OI 增长 ≥ ${r.threshold}%`:`${r.type==='oi'?'1h 币本位 OI':'24h 价格'}变化绝对值从阈值下方进入 ≥ ${r.threshold}%`};
openRule=function(id){
 const rule=activeRules().find(r=>r.id===id)||{p:state.project||state.projects[0],name:'',type:'ema',threshold:5,cooldownMinutes:60,on:true};
 showForm(`${formTitle(id?'编辑后台规则':'新建后台规则')}<p>规则保存在本地服务，关闭网页后仍检查；关闭服务则停止。新建、编辑或重新启用后建立新基线，不补发历史突破。</p><form id="backend-rule-form"><label class="field">规则名称<input name="name" required maxlength="60" value="${escapeHtml(rule.name)}"></label><div class="form-grid"><label class="field">项目<select name="p">${catalog.map(p=>`<option value="${p.id}" ${p.id===rule.p?'selected':''}>${escapeHtml(p.name)}</option>`).join('')}</select></label><label class="field">信号<select name="type">${Object.entries(ruleTypes).map(([k,v])=>`<option value="${k}" ${k===rule.type?'selected':''}>${v}</option>`).join('')}</select></label><label class="field" id="backend-period">K 线周期<select name="period">${[['1h','1 小时'],['4h','4 小时'],['1d','日线（1 天，UTC 收盘）']].map(([v,t])=>`<option value="${v}" ${v===(rule.period||'4h')?'selected':''}>${t}</option>`).join('')}</select></label><label class="field" id="backend-threshold">阈值（% / 关键价位 USD）<input name="threshold" type="number" min="0.000001" max="10000000" step="any" value="${rule.threshold}"></label><label class="field">冷却分钟<input name="cooldownMinutes" type="number" min="1" max="1440" required value="${rule.cooldownMinutes}"></label></div><p class="evidence" id="backend-rule-description"></p><p role="status" id="backend-rule-error"></p><div class="modal-footer"><button class="secondary" type="button" data-close>取消</button><button class="primary" type="submit">保存并监测</button></div></form>`);
 const form=$('#backend-rule-form');const describe=()=>{const type=form.elements.type.value;$('#backend-period').hidden=!['ema','level','combo'].includes(type);$('#backend-threshold').hidden=['news','ema'].includes(type);$('#backend-rule-description').textContent=ruleDescription({type,period:form.elements.period.value,threshold:form.elements.threshold.value})+'。仅站内记录；未连接外部通知。'};form.addEventListener('input',describe);describe();
 form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;const d=Object.fromEntries(new FormData(form));try{await postAPI('/api/rules',{...d,id,period:d.type==='price'?'24h':d.type==='oi'?'1h':d.type==='news'?'4h':d.period,confirm:'close',notify:'site',on:rule.on});state.view='rules';state.project=null;state.query='';$('#search').value='';await refreshLive();$('#form-dialog').close();render();toast('后台规则已保存')}catch(err){$('#backend-rule-error').textContent=err.message;button.disabled=false}});
};
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(!d.editRule&&!d.toggleRule&&!d.deleteRule&&!d.serverDelete)return;
 e.stopImmediatePropagation();
 if(d.editRule){openRule(d.editRule);return}
 if(d.deleteRule){const r=activeRules().find(r=>r.id===d.deleteRule);showForm(`${formTitle('删除规则')}<p>删除「${escapeHtml(r.name)}」后停止检查，已有触发记录保留。</p><div class="modal-footer"><button class="secondary" data-close>取消</button><button class="primary" data-server-delete="${r.id}">确认删除</button></div>`);return}
 try{await postAPI('/api/rules/action',{id:d.toggleRule||d.serverDelete,action:d.toggleRule?'toggle':'delete'});if(d.serverDelete)$('#form-dialog').close();await refreshLive();render()}catch(err){toast(err.message)}
},true);
render();
